using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class TimelineCanvasOperations
{
    public void gui_input(Control owner,InputEvent e)
    {
        if(owner.Get("model").VariantType==Variant.Type.Nil)return;var model=Model(owner);var clips=Clips(owner);var actors=Actors(owner);if(e is InputEventMouseMotion hover&&owner.Get("drag_id").AsString().Length==0){owner.MouseDefaultCursorShape=Control.CursorShape.Arrow;int index=clip_hit_index(owner,hover.Position);if(index>=0){if(owner.Get("split_tool").AsBool()){owner.MouseDefaultCursorShape=Control.CursorShape.Cross;return;}var rect=clip_rect(owner,index);owner.MouseDefaultCursorShape=Math.Min(Math.Abs(hover.Position.X-rect.Position.X),Math.Abs(hover.Position.X-rect.End.X))<=7?Control.CursorShape.Hsize:Control.CursorShape.Drag;}}
        if(e is InputEventMouseButton wheel&&wheel.Pressed&&wheel.ButtonIndex is MouseButton.WheelUp or MouseButton.WheelDown){double amount=(wheel.ButtonIndex==MouseButton.WheelUp?-1:1)*Math.Max(wheel.Factor,1);if(wheel.Position.Y<Header)owner.EmitSignal("scroll_requested",Math.Max(0,N(owner,"scroll_time")+amount*2));else owner.EmitSignal("layer_scroll_requested",Math.Max(0,N(owner,"scroll_rows")+amount*N(owner,"row_height")));owner.AcceptEvent();return;}if(e is InputEventMouseButton right&&right.Pressed&&right.ButtonIndex==MouseButton.Right){int index=clip_hit_index(owner,right.Position);if(index>=0){string id=clips[index].As<Resource>().Get("id").AsString();_timeline.select(model,id,_timeline.is_selected(model,id));}owner.GrabFocus();owner.EmitSignal("context_requested",right.GlobalPosition,index>=0,time_at(owner,right.Position.X),layer_at(owner,right.Position.Y));owner.AcceptEvent();return;}if(e is not InputEventMouseButton button||button.ButtonIndex!=MouseButton.Left||!button.Pressed)return;owner.GrabFocus();owner.AcceptEvent();if(button.Position.Y<Header){if(button.Position.X>=LabelWidth){owner.Set("scrubbing",true);owner.EmitSignal("interaction_changed","Esc cancels scrub");owner.Set("_scrub_origin",owner.Get("playhead"));owner.EmitSignal("time_selected",snapped_playhead(owner,time_at(owner,button.Position.X),button.ShiftPressed,false));}return;}int hit=clip_hit_index(owner,button.Position);if(hit>=0){var rect=clip_rect(owner,hit);if(button.Position.X>=LabelWidth){var clip=clips[hit].As<Resource>();var actor=actors[hit].As<Resource>();string clicked=clip.Get("id").AsString();if(!owner.Get("split_tool").AsBool()&&rect.Size.Y>=16&&rect.Size.X>=20&&actor.Get("type_id").AsString()=="audio")foreach(bool incoming in new[]{true,false})if(fade_handle(owner,hit,incoming).DistanceTo(button.Position)<=7){_timeline.select(model,clicked,_timeline.is_selected(model,clicked));owner.Set("_fade_actor",actor);var key=new StringName(incoming?"fade_in":"fade_out");owner.Set("_fade_key",key);owner.Set("_fade_original",actor.Get("values").AsGodotDictionary().GetValueOrDefault(key,0.0));owner.Set("_fade_pointer",button.GlobalPosition.X);owner.EmitSignal("interaction_changed","Drag audio fade • Esc cancels • Shift disables snap");return;}if(owner.Get("split_tool").AsBool()){_timeline.split_clip(model,clicked,time_at(owner,button.Position.X));return;}if(button.CtrlPressed){_timeline.toggle_selection(model,clicked);return;}_timeline.select(model,clicked,button.ShiftPressed||_timeline.is_selected(model,clicked));owner.Set("drag_id",clicked);owner.EmitSignal("interaction_changed","Esc cancels drag");var ids=List(owner,"_drag_ids");ids.Clear();foreach(string id in _timeline.linked_clip_ids(model,model.Get("selected_ids").AsGodotArray()))ids.Add(id);var originals=owner.Get("_drag_originals").AsGodotDictionary();var previews=owner.Get("_preview_states").AsGodotDictionary();originals.Clear();previews.Clear();foreach(var id in ids){var chosen=clips[_timeline.index_of(model,id.AsString())].As<Resource>();var state=new Settings{["start"]=chosen.Get("start_time"),["duration"]=chosen.Get("duration"),["layer"]=chosen.Get("layer"),["offset"]=chosen.Get("source_offset")};originals[id]=state.Duplicate();previews[id]=state.Duplicate();}double start=clip.Get("start_time").AsDouble(),duration=clip.Get("duration").AsDouble();owner.Set("preview_time",start);owner.Set("preview_duration",duration);owner.Set("preview_layer",clip.Get("layer"));owner.Set("preview_valid",true);owner.Set("_original_start",start);owner.Set("_original_end",start+duration);string mode="move";if(Math.Abs(button.Position.X-rect.Position.X)<=Math.Min(7,rect.Size.X/3))mode="left";else if(Math.Abs(button.Position.X-rect.End.X)<=Math.Min(7,rect.Size.X/3))mode="right";owner.Set("drag_mode",mode);owner.Set("_drag_offset",time_at(owner,button.Position.X)-(mode=="right"?start+duration:start));owner.Set("_pointer_x",button.Position.X);return;}}model.Set("selected_layer",layer_at(owner,button.Position.Y));if(button.Position.X>=LabelWidth&&button.Position.Y>=Header)begin_box_select(owner,button.Position,button.ShiftPressed,button.CtrlPressed);else _timeline.select(model,"",false);
    }
    public void input(Control owner,InputEvent e)
    {
        var fade=owner.Get("_fade_actor").As<Resource>();if(fade!=null){var key=owner.Get("_fade_key").AsStringName();var definition=owner.Get("registry").AsGodotObject().Call("get_definition",new StringName("audio")).As<Resource>();if(e is InputEventMouseMotion motion){double direction=key.ToString()=="fade_in"?1:-1,value=N(owner,"_fade_original")+(motion.GlobalPosition.X-N(owner,"_fade_pointer"))/N(owner,"pixels_per_second")*direction;if(owner.Get("snap_enabled").AsBool()&&!motion.ShiftPressed)value=Mathf.Snapped(value,.1);value=Math.Clamp(value,0,_timeline.clip_for_actor_id(Model(owner),fade.Get("id").AsString())!.Get("duration").AsDouble());_timeline.preview_property(Model(owner),fade,definition,key,value);}else if(e is InputEventMouseButton button&&button.ButtonIndex==MouseButton.Left&&!button.Pressed){_timeline.commit_property_preview(Model(owner),fade,definition,key,owner.Get("_fade_original"),fade.Get("values").AsGodotDictionary()[key]);owner.Set("_fade_actor",default(Variant));owner.EmitSignal("interaction_changed","");}else if(e is InputEventKey keyEvent&&keyEvent.Pressed&&keyEvent.Keycode==Key.Escape)cancel_fade(owner);owner.GetViewport().SetInputAsHandled();return;}bool scrub=owner.Get("scrubbing").AsBool(),box=owner.Get("box_selecting").AsBool();if(owner.Get("drag_id").AsString().Length==0&&!scrub&&!box)return;if(e is InputEventMouseMotion move){var local=owner.GetGlobalTransformWithCanvas().AffineInverse()*move.Position;if(scrub)owner.EmitSignal("time_selected",snapped_playhead(owner,time_at(owner,local.X),move.ShiftPressed,false));else if(box){owner.Set("_box_current",local);update_box_selection(owner,move.ShiftPressed,move.CtrlPressed);owner.EmitSignal("interaction_changed","Esc cancels box select  •  Shift adds  •  Ctrl removes");owner.QueueRedraw();}else{if(owner.Get("drag_mode").AsString()=="move")owner.Set("preview_layer",layer_at(owner,local.Y));update_drag(owner,local.X,move.ShiftPressed);}owner.GetViewport().SetInputAsHandled();}else if(e is InputEventMouseButton release&&release.ButtonIndex==MouseButton.Left&&!release.Pressed){if(scrub){var local=owner.GetGlobalTransformWithCanvas().AffineInverse()*release.Position;owner.EmitSignal("time_selected",snapped_playhead(owner,time_at(owner,local.X),release.ShiftPressed,false));owner.Set("scrubbing",false);owner.EmitSignal("interaction_changed","");}else if(box){owner.Set("box_selecting",false);List(owner,"_box_base_selection").Clear();owner.EmitSignal("interaction_changed","");owner.QueueRedraw();}else finish_drag(owner);owner.GetViewport().SetInputAsHandled();}else if(e is InputEventKey key&&key.Pressed&&key.Keycode==Key.Escape){cancel_drag(owner);owner.GetViewport().SetInputAsHandled();}
    }
}
